    <style>
        body {
            font-family: "SimSun", serif;
            margin: 0;
            padding: 20px;
            background-color: #f5f5f5;
        }
        .page {
            max-width: 1200px;
            margin: 0 auto;
            background-color: white;
            padding: 20px;
        }
        .header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 2px solid #c00;
            padding-bottom: 10px;
            margin-bottom: 20px;
        }
        .logo {
            font-size: 32px;
