            width: 30px;
            height: 30px;
            line-height: 30px;
            text-align: center;
            border-radius: 50%;
            font-size: 18px;
            font-weight: bold;
        }
        .section-title {
            font-size: 14px;
            color: #c00;
            margin-bottom: 5px;
        }
        .main-content {
            display: flex;
            gap: 20px;
        }
        .left-column {
            flex: 2;
        }
        .right-column {
            flex: 1;
            border-left: 1px solid #ddd;
            padding-left: 20px;
        }
